package org.apache.druid.discovery;

import com.google.common.base.Preconditions;
import com.google.common.base.Throwables;
import org.apache.druid.concurrent.LifecycleLock;
import org.apache.druid.java.util.common.IOE;
import org.apache.druid.java.util.common.ISE;
import org.apache.druid.java.util.common.RE;
import org.apache.druid.java.util.common.StringUtils;
import org.apache.druid.java.util.common.lifecycle.LifecycleStart;
import org.apache.druid.java.util.common.lifecycle.LifecycleStop;
import org.apache.druid.java.util.common.logger.Logger;
import org.apache.druid.java.util.http.client.HttpClient;
import org.apache.druid.java.util.http.client.Request;
import org.apache.druid.java.util.http.client.response.FullResponseHolder;
import org.apache.druid.java.util.http.client.response.HttpResponseHandler;
import org.apache.druid.java.util.http.client.response.StringFullResponseHandler;
import org.apache.druid.java.util.http.client.response.StringFullResponseHolder;
import org.jboss.netty.channel.ChannelException;
import org.jboss.netty.handler.codec.http.HttpMethod;
import org.jboss.netty.handler.codec.http.HttpResponseStatus;

import javax.annotation.Nullable;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.Collection;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * This class facilitates interaction with Coordinator/Overlord leader nodes. Instance of this class is injected
 * via Guice with annotations @Coordinator or @IndexingService .
 * Usage:
 * Request request = druidLeaderClient.makeRequest(HttpMethod, requestPath)
 * request.setXXX(..)
 * FullResponseHolder responseHolder = druidLeaderClient.go(request)
 */
public class DruidLeaderClient
{
  private final Logger log = new Logger(DruidLeaderClient.class);

  private static final int MAX_RETRIES = 5;

  private final HttpClient httpClient;
  private final DruidNodeDiscoveryProvider druidNodeDiscoveryProvider;
  private final NodeRole nodeRoleToWatch;

  private final String leaderRequestPath;

  private LifecycleLock lifecycleLock = new LifecycleLock();
  private DruidNodeDiscovery druidNodeDiscovery;
  private AtomicReference<String> currentKnownLeader = new AtomicReference<>();

  public DruidLeaderClient(
      HttpClient httpClient,
      DruidNodeDiscoveryProvider druidNodeDiscoveryProvider,
      NodeRole nodeRoleToWatch,
      String leaderRequestPath
  )
  {
    this.httpClient = httpClient;
    this.druidNodeDiscoveryProvider = druidNodeDiscoveryProvider;
    this.nodeRoleToWatch = nodeRoleToWatch;
    this.leaderRequestPath = leaderRequestPath;
  }

  @LifecycleStart
  public void start()
  {
    if (!lifecycleLock.canStart()) {
      throw new ISE("can't start.");
    }

    try {
      druidNodeDiscovery = druidNodeDiscoveryProvider.getForNodeRole(nodeRoleToWatch);
      lifecycleLock.started();
      log.debug("Started.");
    }
    finally {
      lifecycleLock.exitStart();
    }
  }

  @LifecycleStop
  public void stop()
  {
    if (!lifecycleLock.canStop()) {
      throw new ISE("can't stop.");
    }

    log.debug("Stopped.");
  }

  /**
   * Make a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public Request makeRequest(HttpMethod httpMethod, String urlPath) throws IOException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    return new Request(httpMethod, new URL(StringUtils.format("%s%s", getCurrentKnownLeader(true), urlPath)));
  }

  public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
  {
    return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
  }

  /**
   * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
      throws IOException, InterruptedException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    for (int counter = 0; counter < MAX_RETRIES; counter++) {
      final H fullResponseHolder;
      try {
        try {
          fullResponseHolder = httpClient.go(request, responseHandler).get();
        }
        catch (ExecutionException e) {
          Throwable cause = e.getCause();
          if (cause instanceof IOException) {
            Throwables.propagateIfInstanceOf(cause, IOException.class);
            throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
          } else if (cause instanceof ChannelException) {
            Throwables.propagateIfInstanceOf(cause, ChannelException.class);
            throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
          } else if (cause instanceof InterruptedException) {
            Throwables.propagateIfInstanceOf(cause, IOException.class);
            Throwables.propagateIfInstanceOf(cause, ChannelException.class);
            throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
          } else if (cause instanceof RuntimeException) {
            Throwables.propagateIfInstanceOf(cause, IOException.class);
            Throwables.propagateIfInstanceOf(cause, ChannelException.class);
            throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
          } else {
            Throwables.propagateIfInstanceOf(cause, IOException.class);
            Throwables.propagateIfInstanceOf(cause, ChannelException.class);
            throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
          }
        }
      }
      catch (IOException | ChannelException ex) {
        // can happen if the node is stopped.
        log.warn(ex, "Request[%s] failed.", request.getUrl());
        try {
          URL failedUrl = request.getUrl();
          String failedPath = failedUrl.getPath();
          String failedQuery = failedUrl.getQuery();
          final String resolvedLeader = currentKnownLeader.accumulateAndGet(
              null,
              (current, given) -> {
                Iterator<DiscoveryDruidNode> discoveredNodes = druidNodeDiscovery.getAllNodes().iterator();
                if (discoveredNodes.hasNext()) {
                  DiscoveryDruidNode discoveredNode = discoveredNodes.next();
                  String host = discoveredNode.resolveHost();
                  boolean tlsPreferred = discoveredNode.isTlsPreferred();
                  boolean plaintextPreferred = discoveredNode.isPlaintextPreferred();
                  int tlsPort = discoveredNode.resolveTlsPort();
                  int plaintextPort = discoveredNode.resolvePlaintextPort();
                  String scheme;
                  String hostAndPort;
                  if (tlsPreferred) {
                    if (tlsPort >= 0) {
                      if (host != null) {
                        if (!host.isEmpty()) {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = com.google.common.net.HostAndPort.fromParts(host, tlsPort).toString();
                        } else {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = discoveredNode.resolveHostAndPortToUse();
                        }
                      } else {
                        scheme = discoveredNode.resolveServiceScheme();
                        hostAndPort = discoveredNode.resolveHostAndPortToUse();
                      }
                    } else {
                      scheme = discoveredNode.resolveServiceScheme();
                      hostAndPort = discoveredNode.resolveHostAndPortToUse();
                    }
                  } else if (plaintextPreferred) {
                    if (plaintextPort < 0) {
                      if (host != null) {
                        if (!host.isEmpty()) {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = com.google.common.net.HostAndPort.fromString(host).toString();
                        } else {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = discoveredNode.resolveHostAndPortToUse();
                        }
                      } else {
                        scheme = discoveredNode.resolveServiceScheme();
                        hostAndPort = discoveredNode.resolveHostAndPortToUse();
                      }
                    } else {
                      if (host != null) {
                        if (plaintextPort > 0) {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = com.google.common.net.HostAndPort.fromParts(host, plaintextPort).toString();
                        } else {
                          scheme = discoveredNode.resolveServiceScheme();
                          hostAndPort = com.google.common.net.HostAndPort.fromParts(host, plaintextPort).toString();
                        }
                      } else {
                        scheme = discoveredNode.resolveServiceScheme();
                        hostAndPort = discoveredNode.resolveHostAndPortToUse();
                      }
                    }
                  } else {
                    scheme = discoveredNode.resolveServiceScheme();
                    hostAndPort = discoveredNode.resolveHostAndPortToUse();
                  }
                  if (scheme != null) {
                    if (hostAndPort != null) {
                      if (!hostAndPort.isEmpty()) {
                        return discoveredNode.formatServiceEndpoint(scheme, hostAndPort);
                      }
                      return discoveredNode.toServiceBaseUrl();
                    }
                    return discoveredNode.toServiceBaseUrl();
                  }
                  return discoveredNode.toServiceBaseUrl();
                }
                return null;
              }
          );
          if (resolvedLeader == null) {
            throw new IOE("No known server");
          }
          final URL rebuiltUrl;
          if (failedQuery == null) {
            rebuiltUrl = new URL(DiscoveryDruidNode.formatLeaderRequest(resolvedLeader, failedPath));
          } else if (failedQuery.isEmpty()) {
            rebuiltUrl = new URL(DiscoveryDruidNode.formatLeaderRequest(resolvedLeader, failedPath, failedQuery));
          } else {
            rebuiltUrl = new URL(DiscoveryDruidNode.formatLeaderRequest(resolvedLeader, failedPath, failedQuery));
          }
          HttpMethod retryMethod = request.getMethod();
          Request rebuiltRequest;
          if (HttpMethod.GET.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.GET, rebuiltUrl);
          } else if (HttpMethod.POST.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.POST, rebuiltUrl);
          } else if (HttpMethod.PUT.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.PUT, rebuiltUrl);
          } else if (HttpMethod.DELETE.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.DELETE, rebuiltUrl);
          } else if (HttpMethod.HEAD.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.HEAD, rebuiltUrl);
          } else if (HttpMethod.OPTIONS.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.OPTIONS, rebuiltUrl);
          } else if (HttpMethod.PATCH.equals(retryMethod)) {
            rebuiltRequest = new Request(HttpMethod.PATCH, rebuiltUrl);
          } else {
            rebuiltRequest = new Request(retryMethod, rebuiltUrl);
          }
          for (Map.Entry<String, Collection<String>> headerEntry : request.getHeaders().asMap().entrySet()) {
            String headerName = headerEntry.getKey();
            Collection<String> headerValues = headerEntry.getValue();
            if (headerName != null) {
              if (!headerName.isEmpty()) {
                if (headerValues != null && !headerValues.isEmpty()) {
                  for (String headerValue : headerValues) {
                    rebuiltRequest.addHeader(headerName, headerValue);
                  }
                }
              } else if (headerValues != null) {
                for (String headerValue : headerValues) {
                  rebuiltRequest.addHeader(headerName, headerValue);
                }
              }
            }
          }
          if (request.hasContent()) {
            rebuiltRequest.setContent(request.getContent());
          }
          request = rebuiltRequest;
          continue;
        }
        catch (MalformedURLException e) {
          // Not an IOException; this is our own fault.
          throw new ISE(
              e,
              "failed to build url with path[%] and query string [%s].",
              request.getUrl().getPath(),
              request.getUrl().getQuery()
          );
        }
      }

      HttpResponseStatus responseStatus = fullResponseHolder.getResponse().getStatus();
      if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(responseStatus)) {
        String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
        if (redirectUrlStr == null) {
          throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
        }

        log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

        final URL redirectUrl;
        try {
          redirectUrl = new URL(redirectUrlStr);
        }
        catch (MalformedURLException ex) {
          throw new IOE(
              ex,
              "Malformed redirect location is found in response from url[%s], new location[%s].",
              request.getUrl(),
              redirectUrlStr
          );
        }

        String redirectProtocol = redirectUrl.getProtocol();
        String redirectHost = redirectUrl.getHost();
        if (redirectProtocol != null) {
          if ("https".equalsIgnoreCase(redirectProtocol)) {
            currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
          } else if ("http".equalsIgnoreCase(redirectProtocol)) {
            if (redirectHost != null) {
              if (!redirectHost.isEmpty()) {
                currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
              } else {
                currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
              }
            } else {
              currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
            }
          } else {
            currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
          }
        } else {
          currentKnownLeader.set(DiscoveryDruidNode.formatLeaderFromRedirect(redirectUrl));
        }

        HttpMethod redirectMethod = request.getMethod();
        Request redirectedRequest;
        if (HttpMethod.GET.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.GET, redirectUrl);
        } else if (HttpMethod.POST.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.POST, redirectUrl);
        } else if (HttpMethod.PUT.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.PUT, redirectUrl);
        } else if (HttpMethod.DELETE.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.DELETE, redirectUrl);
        } else if (HttpMethod.HEAD.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.HEAD, redirectUrl);
        } else if (HttpMethod.OPTIONS.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.OPTIONS, redirectUrl);
        } else if (HttpMethod.PATCH.equals(redirectMethod)) {
          redirectedRequest = new Request(HttpMethod.PATCH, redirectUrl);
        } else {
          redirectedRequest = new Request(redirectMethod, redirectUrl);
        }
        for (Map.Entry<String, Collection<String>> headerEntry : request.getHeaders().asMap().entrySet()) {
          String headerName = headerEntry.getKey();
          Collection<String> headerValues = headerEntry.getValue();
          if (headerName != null) {
            if (!headerName.isEmpty()) {
              if (headerValues != null && !headerValues.isEmpty()) {
                for (String headerValue : headerValues) {
                  redirectedRequest.addHeader(headerName, headerValue);
                }
              }
            } else if (headerValues != null) {
              for (String headerValue : headerValues) {
                redirectedRequest.addHeader(headerName, headerValue);
              }
            }
          }
        }
        if (request.hasContent()) {
          redirectedRequest.setContent(request.getContent());
        }
        request = redirectedRequest;
      } else {
        return fullResponseHolder;
      }
    }

    throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
  }

  public String findCurrentLeader()
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    final StringFullResponseHolder responseHolder;
    try {
      responseHolder = go(makeRequest(HttpMethod.GET, leaderRequestPath));
    }
    catch (Exception ex) {
      throw new ISE(ex, "Couldn't find leader.");
    }

    if (responseHolder.getStatus().getCode() == 200) {
      String leaderUrl = responseHolder.getContent();

      //verify this is valid url
      try {
        URL validatedUrl = new URL(leaderUrl);
        currentKnownLeader.set(leaderUrl);

        // validatedUrl.toString() is returned instead of leaderUrl or else teamcity build fails because of breaking
        // the rule of ignoring new URL(leaderUrl) object.
        return validatedUrl.toString();
      }
      catch (MalformedURLException ex) {
        log.error(ex, "Received malformed leader url[%s].", leaderUrl);
      }
    }

    throw new ISE(
        "Couldn't find leader, failed response status is [%s] and content [%s].",
        responseHolder.getStatus().getCode(),
        responseHolder.getContent()
    );
  }

  private String getCurrentKnownLeader(final boolean cached) throws IOException
  {
    final String leader = currentKnownLeader.accumulateAndGet(
        null,
        (current, given) -> current == null || !cached ? pickOneHost() : current
    );

    if (leader == null) {
      throw new IOE("No known server");
    } else {
      return leader;
    }
  }

  @Nullable
  private String pickOneHost()
  {
    Iterator<DiscoveryDruidNode> iter = druidNodeDiscovery.getAllNodes().iterator();
    if (iter.hasNext()) {
      return iter.next().toServiceBaseUrl();
    }

    return null;
  }

  private Request withUrl(Request old, URL url)
  {
    Request req = new Request(old.getMethod(), url);
    req.addHeaderValues(old.getHeaders());
    if (old.hasContent()) {
      req.setContent(old.getContent());
    }
    return req;
  }
}

